/** MIT; externally prescribed smooth appearance only,no elasticity orhinges. */
import * as THREE from 'three';import{Component}from'../../core/index.js';
export class StripFlex extends Component{
 static kind='flexible-strip';
 constructor(){super({id:'flex',label:'A035 neutral-axis bend',meta:{role:'externally-driven-flexible-strip',rangeDeg:[-120,120],neutralAxisLengthMm:100,scope:'External circular-arc appearance only;no elastic/material/force/minimum-rated-radius orfirmware model'}});this.surfaces=[];this.sites=[];this.links=[];this.bendDeg=0;this.transition=null;}
 point(x,y,z=0){const k=THREE.MathUtils.degToRad(this.bendDeg)/100;if(k===0)return new THREE.Vector3(x,y,z);const t=k*y;return new THREE.Vector3(x,Math.sin(t)/k-z*Math.sin(t),(1-Math.cos(t))/k+z*Math.cos(t));}
 basis(y){return new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(1,0,0),THREE.MathUtils.degToRad(this.bendDeg)*y/100);}
 surface(mesh){const g=mesh.geometry;this.surfaces.push({mesh,p:new Float32Array(g.attributes.position.array),n:g.attributes.normal?new Float32Array(g.attributes.normal.array):null});return mesh;}
 site(object,y,rotation=new THREE.Quaternion()){this.sites.push({object,y,rotation:rotation.clone()});object.position.set(0,y,0);object.quaternion.copy(rotation);return object;}
 link(mesh,stripPoint,rigid,rigidPoint){this.links.push({mesh,stripPoint,rigid,rigidPoint:new THREE.Vector3(...rigidPoint)});return mesh;}
 apply(){const k=THREE.MathUtils.degToRad(this.bendDeg)/100;for(const s of this.surfaces){const p=s.mesh.geometry.attributes.position,n=s.mesh.geometry.attributes.normal;if(k===0){p.array.set(s.p);if(n&&s.n)n.array.set(s.n);}else for(let i=0;i<p.count;i++){const x=s.p[i*3],y=s.p[i*3+1],z=s.p[i*3+2],t=k*y,cs=Math.cos(t),sn=Math.sin(t);p.setXYZ(i,x,Math.sin(t)/k-z*sn,(1-cs)/k+z*cs);if(n&&s.n){const nx=s.n[i*3],ny=s.n[i*3+1]/(1-k*z),nz=s.n[i*3+2],v=new THREE.Vector3(nx,ny*cs-nz*sn,ny*sn+nz*cs).normalize();n.setXYZ(i,v.x,v.y,v.z);}}p.needsUpdate=true;if(n)n.needsUpdate=true;s.mesh.geometry.computeBoundingBox();s.mesh.geometry.computeBoundingSphere();}
  for(const s of this.sites){s.object.position.copy(this.point(0,s.y));s.object.quaternion.copy(this.basis(s.y)).multiply(s.rotation);}for(const l of this.links){const a=this.point(...l.stripPoint),b=l.rigidPoint.clone().applyQuaternion(l.rigid.quaternion).add(l.rigid.position),d=b.clone().sub(a);l.mesh.position.copy(a).add(b).multiplyScalar(.5);l.mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.clone().normalize());l.mesh.scale.set(1,d.length(),1);}if(this.host?.unitFrame)this.host.unitFrame.bindInput(this.host.get('grove'));this.host?.cable?.sync();this.requestRender();}
 set({bendDeg,durationMs=0}={}){if(!Number.isFinite(bendDeg)||bendDeg< -120||bendDeg>120)throw new RangeError('bendDeg must be finite within[-120,120]');if(!Number.isFinite(durationMs)||durationMs<0)throw new RangeError('durationMs must be finite >=0');this.transition=durationMs>0&&bendDeg!==this.bendDeg?{from:this.bendDeg,to:bendDeg,elapsed:0,duration:durationMs/1000}:null;if(!this.transition){this.bendDeg=bendDeg;this.apply();}this.requestRender();return this.getState();}
 update(dt=0){if(!Number.isFinite(dt)||dt<0)throw new RangeError('dt must be finite >=0');if(!this.transition)return false;const t=this.transition;t.elapsed=Math.min(t.duration,t.elapsed+dt);this.bendDeg=t.from+(t.to-t.from)*t.elapsed/t.duration;this.apply();if(t.elapsed>=t.duration)this.transition=null;return true;}
 handle(cmd){if(cmd.type==='flex')return this.set(cmd);if(cmd.type==='state')return this.getState();return super.handle(cmd);}
 getState(){return{bendDeg:this.bendDeg,targetBendDeg:this.transition?.to??this.bendDeg,transitioning:this.transition!==null,neutralAxisLengthMm:100,rangeDeg:[-120,120]};}
}
